import { Link, useParams } from 'react-router-dom';
import { useEffect, useState } from 'react';
import { productApi } from '../services/api';
import { useStore } from '../context/StoreContext';
import './ProductDetailsPage.css';

function formatPrice(product) {
  if (!product || product.price === null || product.price === undefined) return 'Check latest price';
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: product.currency || 'USD' }).format(product.price);
  } catch {
    return `${product.currency || '$'} ${product.price}`;
  }
}

function ProductDetailsPage() {
  const { productId } = useParams();
  const { addToCart, toggleWishlist } = useStore();
  const [product, setProduct] = useState(null);
  const [activeImage, setActiveImage] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    let active = true;
    setLoading(true);
    productApi
      .getProduct(productId)
      .then((data) => {
        if (!active) return;
        setProduct(data.product);
        setActiveImage(data.product?.image || data.product?.images?.[0] || '');
      })
      .catch((err) => active && setError(err.response?.data?.message || 'Product details could not be loaded.'))
      .finally(() => active && setLoading(false));
    return () => {
      active = false;
    };
  }, [productId]);

  if (loading) {
    return <div className="container section"><div className="loading-skeleton" style={{ height: 520 }} /></div>;
  }

  if (error || !product) {
    return <div className="container section"><div className="empty-state"><h2>Product not found</h2><p>{error}</p><Link className="btn btn-primary" to="/products">Back to products</Link></div></div>;
  }

  const images = product.images?.length ? product.images : [product.image].filter(Boolean);
  const specs = Object.entries(product.specifications || {}).filter(([, value]) => value !== null && value !== undefined && value !== '');

  return (
    <section className="product-detail-page container section">
      <div className="breadcrumb"><Link to="/">Home</Link> › <Link to="/products">Products</Link> › <span>{product.title}</span></div>
      <div className="detail-grid">
        <div className="detail-gallery card">
          <div className="detail-main-image">
            {activeImage ? <img src={activeImage} alt={product.title} /> : <div>No image available</div>}
          </div>
          <div className="detail-thumbs">
            {images.slice(0, 8).map((image) => (
              <button key={image} className={image === activeImage ? 'active' : ''} onClick={() => setActiveImage(image)}><img src={image} alt="thumbnail" /></button>
            ))}
          </div>
        </div>
        <div className="detail-info card">
          <span className="badge">{product.source} · {product.brand} · {product.category}</span>
          <h1>{product.title}</h1>
          <p>{product.description}</p>
          <div className="detail-price">{formatPrice(product)}</div>
          <div className="detail-stats">
            <span>★ {product.rating ? Number(product.rating).toFixed(1) : 'N/A'} rating</span>
            <span>{product.reviewCount || 0} reviews</span>
            <span>{product.availability || 'Check seller'}</span>
          </div>
          <div className="detail-actions">
            <button className="btn btn-primary" onClick={() => addToCart(product)}>Add to Cart</button>
            <button className="btn btn-secondary" onClick={() => toggleWishlist(product)}>Save to Wishlist</button>
            {product.productUrl && <a className="btn btn-secondary" href={product.productUrl} target="_blank" rel="noreferrer">Open Original Listing</a>}
          </div>
        </div>
      </div>
      <div className="detail-section card">
        <h2>Specifications</h2>
        <div className="detail-spec-grid">
          {specs.length === 0 && <p>Specifications are not available from this provider.</p>}
          {specs.slice(0, 24).map(([key, value]) => <div key={key}><strong>{key}</strong><span>{String(value)}</span></div>)}
        </div>
      </div>
    </section>
  );
}

export default ProductDetailsPage;
